import {SocialClient,normalizeUsername} from './social.js';
import {TRACKS} from './simulation.js';
const socialEscape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountSocialUI({config,lan,getName,getRace,isPaused,pause,onJoin}){
 const el=id=>document.getElementById(id),visible=(id,on)=>el(id).classList.toggle('hidden',!on),overlay=el('social-overlay');let busy=false,resumeRace=false,noticeTimer=null;
 const presence=()=>{const state=lan.backend==='supabase'?lan.state:null;return{activity:state?.status==='lobby'?'lobby':state?.status==='race'?'race':getRace()?'race':'available',lobbyCode:state?.status==='lobby'||state?.status==='race'?state.code:null,trackId:state?.options.trackId||null};};
 const inRace=()=>!!getRace()&&getRace().state!=='finished',canInvite=()=>lan.backend==='supabase'&&lan.state?.status==='lobby'&&lan.cloud.config?.url===config.url;
 const client=new SocialClient(config,{onUpdate:render,onInvite:invite=>{el('social-notice-text').textContent=`@${invite.from.username} ti invita in lobby`;visible('social-notice',true);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>visible('social-notice',false),12000);noticeTimer.unref?.();},getPresence:presence});
 const actionButton=(action,id,label,disabled=false)=>`<button type="button" class="social-action" data-social-action="${action}" data-id="${socialEscape(id)}" ${disabled?'disabled':''}>${label}</button>`;
 function render(){
  visible('social-export',!client.accountToken);visible('social-import',!client.accountToken);
  const data=client.data,profile=client.profile,count=(data?.incoming.length||0)+(data?.invites.length||0);el('social-nav').textContent=count?`AMICI · ${count}`:'AMICI';el('social-hud').setAttribute('aria-label',count?`Amici, ${count} novità`:'Apri amici');el('social-badge').textContent=count||'';visible('social-badge',count>0);visible('social-register',!client.connected);visible('social-content',client.connected);el('social-profile').textContent=profile?'@'+profile.username:'IL TUO PROFILO PILOTA';el('social-status').textContent=busy?'Operazione in corso…':client.error||client.message||(client.connected?(data?'Amici e inviti aggiornati.':'Collegamento agli amici…'):'Scegli un nome univoco per farti trovare dagli amici.');el('social-save-note').textContent=client.accountToken?'Amici e inviti sono collegati al tuo account. Accedi con nome utente e password sugli altri dispositivi.':client.saved?'Il profilo resta in questo browser. Salva l’accesso per usarlo anche su un altro PC.':'Questo browser non ha salvato il profilo. Premi Salva accesso prima di chiudere.';el('social-export').disabled=!client.connected||busy;el('social-refresh').disabled=!client.connected||busy;el('social-add-button').disabled=busy;el('social-create-button').disabled=busy;el('social-friend-name').disabled=busy;el('social-username').disabled=busy;el('social-import').disabled=busy;
  if(!data){el('social-friends').innerHTML='<p class="social-empty">'+(client.connected?'Caricamento amici…':'')+'</p>';return;}
  el('social-invite-hint').textContent=canInvite()?'La tua lobby è pronta: premi Invita accanto a un amico.':inRace()?'Potrai entrare in un invito dopo la gara.':'Crea una lobby online per invitare i tuoi amici.';
  el('social-friend-count').textContent=String(data.friends.length);
  el('social-friends').innerHTML=data.friends.length?data.friends.map(f=>`<div class="social-person"><span class="social-dot ${f.online?'online':''}"></span><div class="social-person-name"><b>@${socialEscape(f.username)}</b><small>${f.online?(f.activity==='lobby'?'In lobby':f.activity==='race'?'In gara':'Online'):'Offline'}</small></div><div class="social-actions">${actionButton('invite',f.id,'INVITA',busy||!f.online||!canInvite())}${actionButton('remove',f.id,'Rimuovi',busy)}</div></div>`).join(''):'<p class="social-empty">La griglia degli amici è vuota. Aggiungi il primo pilota qui sopra.</p>';
  el('social-requests').innerHTML=data.incoming.length?data.incoming.map(f=>`<div class="social-person"><div class="social-person-name"><b>@${socialEscape(f.username)}</b><small>Vuole aggiungerti agli amici</small></div><div class="social-actions">${actionButton('accept',f.relationshipId,'ACCETTA',busy)}${actionButton('reject',f.relationshipId,'Rifiuta',busy)}</div></div>`).join(''):'<p class="social-empty">Nessuna richiesta da confermare.</p>';
  el('social-outgoing').innerHTML=data.outgoing.map(f=>`<div class="social-person"><div class="social-person-name"><b>@${socialEscape(f.username)}</b><small>Richiesta inviata · in attesa</small></div>${actionButton('remove',f.id,'Annulla',busy)}</div>`).join('');
  el('social-invites').innerHTML=data.invites.length?data.invites.map(invite=>`<div class="social-invite"><span class="eyebrow">INVITO ALLA LOBBY</span><b>@${socialEscape(invite.from.username)}</b><p>${socialEscape(TRACKS.find(t=>t.id===invite.trackId)?.name||'Gran Premio')} · valido per pochi minuti</p><div class="social-actions">${actionButton('join',invite.id,inRace()?'DOPO LA GARA':'ENTRA IN LOBBY',busy||inRace())}${actionButton('dismiss',invite.id,'Rifiuta',busy)}</div></div>`).join(''):'<p class="social-empty">Quando un amico ti invita, potrai entrare qui con un clic.</p>';
  document.querySelectorAll('[data-social-action]').forEach(button=>button.addEventListener('click',()=>run(async()=>{const id=button.dataset.id;switch(button.dataset.socialAction){case'invite':if(!canInvite())throw Error('Crea prima una lobby online sul server ApexGP.');await client.invite(id,lan.state.code,lan.state.options.trackId);break;case'remove':await client.remove(id);break;case'accept':await client.respond(id,true);break;case'reject':await client.respond(id,false);break;case'dismiss':await client.dismissInvite(id);break;case'join':{if(inRace())throw Error('Completa la gara prima di entrare in un’altra lobby.');const {roomCode}=await client.acceptInvite(id);const joined=await onJoin(roomCode);if(joined){await client.dismissInvite(id);close(false);}else throw Error('Lobby non disponibile. Puoi riprovare o chiedere un nuovo invito.');break;}}})));
 }
 async function run(operation){if(busy)return;busy=true;client.error='';render();try{await operation();}catch(e){client.error=e.message;render();}finally{busy=false;render();}}
 function open(){if(overlay.classList.contains('hidden')){const race=getRace();resumeRace=!!race&&race.state!=='finished'&&!isPaused();if(resumeRace)pause(true);}visible('social-overlay',true);visible('social-notice',false);if(!client.connected)el('social-username').value=normalizeUsername(getName()).replace(/[^a-z0-9_]/g,'').slice(0,20);render();el(client.connected?'social-close':'social-username').focus();if(client.connected)client.refresh().catch(()=>{});}
 function close(resume=true){visible('social-overlay',false);if(resume&&resumeRace)pause(false);resumeRace=false;}
 for(const id of ['social-nav','social-hud','social-open','lobby-friends','social-notice-open'])el(id).addEventListener('click',open);
 el('social-close').addEventListener('click',()=>close());el('social-refresh').addEventListener('click',()=>run(()=>client.refresh()));
 el('social-create-form').addEventListener('submit',event=>{event.preventDefault();run(()=>client.register(el('social-username').value,getName()));});
 el('social-add-form').addEventListener('submit',event=>{event.preventDefault();run(async()=>{await client.request(el('social-friend-name').value);el('social-friend-name').value='';});});
 el('social-export').addEventListener('click',()=>{try{const url=URL.createObjectURL(new Blob([client.exportAccess()],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ApexGP-accesso-'+client.profile.username+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);client.message='Accesso salvato: conserva questo file per te, permette di usare il tuo profilo.';render();}catch(e){client.error=e.message;render();}});
 el('social-import').addEventListener('click',()=>el('social-access-file').click());el('social-access-file').addEventListener('change',()=>run(async()=>{const file=el('social-access-file').files?.[0];if(!file)return;if(file.size>8192)throw Error('File di accesso non valido.');await client.restore(await file.text());el('social-access-file').value='';}));
 render();client.start();return{client,open,close,refresh:()=>client.refresh(),isOpen:()=>!overlay.classList.contains('hidden'),presenceChanged:()=>{render();if(client.connected)client.refresh().catch(()=>{});}};
}
